/* A fixed snapshot plus immutable, small change batches. Full reads only on first setup/manual review. */
(function(w){'use strict';
const lists=['gaku-ui-data','gaku-ui-kanji','gaku-ui-history'];
const stable=v=>JSON.stringify(v&&typeof v==='object'?Array.isArray(v)?v.map(x=>JSON.parse(stable(x))):Object.fromEntries(Object.keys(v).sort().map(k=>[k,JSON.parse(stable(v[k]))])):v);
const same=(a,b)=>a===b;
function entries(values){w.GakuCloud.validate(values);const out={};for(const group of w.GakuCloud.KEYS){const raw=values[group];if(raw===null)continue;out[JSON.stringify([group,'$'])]=lists.includes(group)?'[]':stable(JSON.parse(raw));if(!lists.includes(group))continue;const used=new Map();for(const row of JSON.parse(raw)){if(!row||typeof row!=='object'||Array.isArray(row))throw Error('Baris data tidak sesuai.');const identity=group==='gaku-ui-history'?(row.historyId||row.quiz?.id||row.buku?.attempt||row.id||stable(row)):(row.customId||[row.level||'N5',row.jp]);const tag=stable(identity),n=used.get(tag)||0;used.set(tag,n+1);out[JSON.stringify([group,'r:'+tag+':'+n])]=stable(row);}}return out;}
function values(map){const out=Object.fromEntries(w.GakuCloud.KEYS.map(k=>[k,null])),rows={};for(const [key,value] of Object.entries(map)){const [group,tag]=JSON.parse(key);if(!w.GakuCloud.KEYS.includes(group)||typeof value!=='string')throw Error('Perubahan tidak sesuai.');if(tag==='$')out[group]=value;else if(lists.includes(group)&&tag.startsWith('r:'))(rows[group]??=[]).push(JSON.parse(value));else throw Error('Jenis perubahan tidak sesuai.');}for(const group of lists)if(out[group]!==null){const r=rows[group]||[];if(group==='gaku-ui-history')r.sort((a,b)=>(Date.parse(b.time)||0)-(Date.parse(a.time)||0));out[group]=JSON.stringify(r);}return w.GakuCloud.validate(out);}
function diff(before,after){return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>!same(before[k],after[k])).map(k=>[k,after[k]??null]);}
function apply(base,ops){const out={...base};if(!Array.isArray(ops))throw Error('Daftar perubahan tidak sesuai.');for(const op of ops){if(!Array.isArray(op)||op.length!==2||typeof op[0]!=='string'||(op[1]!==null&&typeof op[1]!=='string'))throw Error('Perubahan rusak.');if(op[1]===null)delete out[op[0]];else out[op[0]]=op[1];}values(out);return out;}
function merge(base,local,remote){const a=diff(base,local),b=new Map(diff(base,remote));if(a.some(([k,v])=>b.has(k)&&b.get(k)!==v))return null;return apply(remote,a);}
function guard(uid){if(w.GakuAuth?.user?.uid!==uid)throw Error('Akun berubah.');}
async function connect(uid){guard(uid);const sdk=await import('https://www.gstatic.com/firebasejs/13.2.0/firebase-firestore.js');guard(uid);return {sdk,db:sdk.getFirestore(w.GakuAuth.firebaseApp)};}
function refs(sdk,db,uid,epoch){return {root:sdk.doc(db,'users',uid,'study','snapshot'),head:sdk.doc(db,'users',uid,'study','syncHead'),changes:epoch?sdk.collection(db,'users',uid,'studyEpochs',String(epoch),'changes'):null};}
function head(doc){if(!doc.exists())return null;const d=doc.data();if(d.version!==2||!Number.isInteger(d.epoch)||d.epoch<1||!Number.isInteger(d.seq)||d.seq<0)throw Error('Penanda perubahan tidak sesuai.');return {epoch:d.epoch,seq:d.seq};}
function event(doc,epoch){const d=doc.data();if(d.version!==2||d.epoch!==epoch||!Number.isInteger(d.seq)||d.seq<1||typeof d.ops!=='string')throw Error('Catatan perubahan tidak sesuai.');return {seq:d.seq,ops:JSON.parse(d.ops)};}
async function ensure(uid){const {sdk,db}=await connect(uid),r=refs(sdk,db,uid);let h=head(await sdk.getDocFromServer(r.head));guard(uid);if(h)return h;await sdk.runTransaction(db,async tx=>{guard(uid);const current=head(await tx.get(r.head));if(current){h=current;return;}const snap=await tx.get(r.root);if(!snap.exists())throw Error('Belum ada cadangan. Gunakan Simpan ke akun dahulu.');const d=snap.data();w.GakuCloud.validate(JSON.parse(d.payload));h={epoch:d.revision,seq:0};tx.set(r.head,{version:2,...h,updatedAt:sdk.serverTimestamp()});});guard(uid);return h;}
async function load(uid){const {sdk,db}=await connect(uid);for(let attempt=0;attempt<3;attempt++){const h=await ensure(uid),r=refs(sdk,db,uid,h.epoch),root=await sdk.getDocFromServer(r.root);guard(uid);if(!root.exists()||root.data().revision!==h.epoch)continue;let map=entries(w.GakuCloud.validate(JSON.parse(root.data().payload)));if(h.seq){const docs=await sdk.getDocs(sdk.query(r.changes,sdk.where('seq','<=',h.seq)));guard(uid);const events=docs.docs.map(d=>event(d,h.epoch)).sort((a,b)=>a.seq-b.seq);if(events.length!==h.seq||events.some((e,i)=>e.seq!==i+1))throw Error('Riwayat perubahan belum lengkap. Coba lagi.');for(const e of events)map=apply(map,e.ops);}return {revision:h.epoch,sequence:h.seq,values:values(map),date:'Cadangan akun terbaru'};}throw Error('Cadangan sedang berubah. Coba lagi.');}
async function verify(uid,expected){const h=await ensure(uid);guard(uid);if(h.epoch!==expected?.revision||h.seq!==(expected.sequence||0))throw Error('Cadangan akun berubah. Periksa ulang.');return expected;}
async function publish(uid,data,expected){if(expected&&!diff(entries(expected.values),entries(data)).length){await verify(uid,expected);return {epoch:expected.revision,seq:expected.sequence||0};}const {sdk,db}=await connect(uid),r=refs(sdk,db,uid);w.GakuCloud.validate(data);let epoch;await sdk.runTransaction(db,async tx=>{guard(uid);const root=await tx.get(r.root),h=head(await tx.get(r.head)),current=root.exists()?root.data().revision:0;if(current!==(expected?.revision||0)||(h?.seq||0)!==(expected?.sequence||0))throw Error('Cadangan akun berubah. Periksa ulang.');epoch=current+1;tx.set(r.root,{version:1,revision:epoch,payload:JSON.stringify(data),updatedAt:sdk.serverTimestamp()});tx.set(r.head,{version:2,epoch,seq:0,updatedAt:sdk.serverTimestamp()});});guard(uid);return {epoch,seq:0};}
async function append(uid,baseline,ops){if(!ops.length)return baseline.seq;const {sdk,db}=await connect(uid),r=refs(sdk,db,uid,baseline.epoch);const text=JSON.stringify(ops);if(new TextEncoder().encode(text).length>700000)throw Error('Perubahan terlalu besar. Gunakan Simpan manual.');await sdk.runTransaction(db,async tx=>{guard(uid);const current=head(await tx.get(r.head));if(!current||current.epoch!==baseline.epoch||current.seq!==baseline.seq){const e=Error('Ada perubahan dari perangkat lain.');e.retry=true;throw e;}tx.set(sdk.doc(r.changes,String(current.seq+1)),{version:2,epoch:current.epoch,seq:current.seq+1,ops:text,updatedAt:sdk.serverTimestamp()});tx.set(r.head,{version:2,epoch:current.epoch,seq:current.seq+1,updatedAt:sdk.serverTimestamp()});});guard(uid);return baseline.seq+1;}
async function watch(uid,baseline,onHead,onEvents,onError){const {sdk,db}=await connect(uid),r=refs(sdk,db,uid,baseline.epoch);let a=()=>{},b=()=>{};const valid=d=>!d.metadata?.fromCache&&!d.metadata?.hasPendingWrites;try{a=sdk.onSnapshot(r.head,{includeMetadataChanges:true},d=>{if(valid(d))try{guard(uid);onHead(head(d));}catch(e){onError(e);}},onError);b=sdk.onSnapshot(sdk.query(r.changes,sdk.where('seq','>',baseline.seq)),{includeMetadataChanges:true},q=>{if(valid(q))try{guard(uid);onEvents(q.docChanges({includeMetadataChanges:true}).filter(c=>c.type!=='removed'&&valid(c.doc)).map(c=>event(c.doc,baseline.epoch)));}catch(e){onError(e);}},onError);}catch(e){a();b();throw e;}return ()=>{a();b();};}
w.GakuDelta={entries,values,diff,apply,merge,ensure,load,verify,publish,append,watch};
})(window);
